window.BANK={"version":"1.0, 2026-11-20","categories":[{"key":"PAR","name":"Paradigms of International Relations","short":"Paradigms"},{"key":"REG","name":"International Regimes","short":"Regimes"},{"key":"ECO","name":"Economic Tools","short":"Economic Tools"},{"key":"SEC","name":"The Security Dilemma","short":"Security Dilemma"},{"key":"NUC","name":"Nuclear Revolution","short":"Nuclear"},{"key":"GRB","name":"Grab Bag","short":"Grab Bag"}],"values":[100,200,300,400,500],"items":[{"id":"PAR-100-1","cat":"PAR","value":100,"week":1,"reading":"Waltz","slide":"The System Has Three Big Features","clue":"In Waltz's account, what word describes an international system with no global police force and no authority above states?","answer":"Anarchy","choices":["Anarchy","Hierarchy","Hegemony","Polarity"],"explain":"Anarchy does not mean chaos. It means there is no overarching authority above states."},{"id":"PAR-100-2","cat":"PAR","value":100,"week":2,"reading":"Nye & Welch","slide":"Power","clue":"What do we call the ability to get others to want what you want, through persuasion and not coercion?","answer":"Soft power","choices":["Soft power","Hard power","Relative power","Fungibility"],"explain":"Hard power gets another actor to do what it otherwise would not; soft power gets others to want what you want."},{"id":"PAR-100-3","cat":"PAR","value":100,"week":1,"reading":"Nye","slide":"Realism","clue":"Which paradigm holds that states are the dominant actors, power is the key difference between them, and competition is their primary interaction?","answer":"Realism","choices":["Realism","Liberalism","Constructivism","Marxism"],"explain":"For realists, all of international politics sits in the shadow of potential conflict, and even cooperation reflects the balance of power."},{"id":"PAR-100-4","cat":"PAR","value":100,"week":2,"reading":"Nye & Welch (and Week 11)","slide":"IR System Power Configurations","clue":"What term describes an international system with two dominant powers, as in the Cold War?","answer":"Bipolar","choices":["Bipolar","Unipolar","Multipolar","Hegemonic"],"explain":"Unipolar means one dominant power, bipolar two, and multipolar three or more."},{"id":"PAR-200-1","cat":"PAR","value":200,"week":2,"reading":"Mearsheimer","slide":"Mearsheimer: Offensive Realism","clue":"Which scholar says states are not status quo powers until they dominate the system?","answer":"Mearsheimer","choices":["Mearsheimer","Waltz","Nye","Krasner"],"explain":"In this theory, great powers always have some offensive military capability and stay ambitious until they dominate."},{"id":"PAR-200-2","cat":"PAR","value":200,"week":2,"reading":"Keck & Sikkink","slide":"Who's in an Advocacy Network?","clue":"Which pair of scholars studied transnational advocacy networks, made up of NGOs, social movements, foundations, media, and others working across borders?","answer":"Keck and Sikkink","choices":["Keck and Sikkink","Nye and Welch","Martin and Simmons","Farrell and Newman"],"explain":"Keck and Sikkink describe networks with voluntary, reciprocal, and horizontal patterns of communication and exchange."},{"id":"PAR-200-3","cat":"PAR","value":200,"week":2,"reading":"Krasner","slide":"Does Globalization Undermine Sovereignty?","clue":"Which scholar argued in 2001 that globalization's challenge to sovereignty is nothing new, because states have long struggled with this tension?","answer":"Krasner","choices":["Krasner","Mearsheimer","Rodrik","Keohane"],"explain":"Krasner asks whether sovereignty is real or just convenient, and says the tension with globalization is an old one."},{"id":"PAR-200-4","cat":"PAR","value":200,"week":3,"reading":"Art","slide":"Two Reasons Military Power Still Matters","clue":"Which scholar asks why military power remains so essential to statecraft, and gives two fundamental reasons?","answer":"Art","choices":["Art","Nye","Etzioni","Lind"],"explain":"Art's first reason is that the system is anarchic, so foreign policy and military power work together."},{"id":"PAR-300-1","cat":"PAR","value":300,"week":2,"reading":"Keck & Sikkink","slide":"The Boomerang Pattern","clue":"Activists blocked at home enlist allies abroad, who then put pressure back on the activists' own government. What do Keck and Sikkink call this pattern?","answer":"The boomerang pattern","choices":["The boomerang pattern","Bandwagoning","Issue linkage","Weaponized interdependence"],"explain":"When domestic channels are blocked, the path runs from domestic to international and back to domestic."},{"id":"PAR-300-2","cat":"PAR","value":300,"week":3,"reading":"Preview of constructivism","slide":"Preview: Constructivism","clue":"According to the course's preview of constructivism, what is true of identities and interests in the international system?","answer":"They are constructed and subjective, not fixed or given","choices":["They are constructed and subjective","They are fixed by the distribution of power","They are set by economic class","They are determined by geography"],"explain":"The big takeaway of constructivism: identities and interests are constructed and subjective, not fixed and not given."},{"id":"PAR-300-3","cat":"PAR","value":300,"week":3,"reading":"Art","slide":"How Does Force Achieve Fungibility?","clue":"A state's military strength wins it better terms in a trade negotiation. Art says force can be used for a wide variety of tasks, military and nonmilitary. What is his word for this quality?","answer":"Fungibility (force is fungible)","choices":["Fungibility","Soft power","Polarity","Sovereignty"],"explain":"Force achieves fungibility through spillover effects and issue linkages."},{"id":"PAR-300-4","cat":"PAR","value":300,"week":3,"reading":"Nye","slide":"Five Trends Driving the Diffusion of Power","clue":"Nye lists five trends driving the diffusion of power. Name one.","answer":"Any one of: economic interdependence, transnational actors, nationalism in weak states, the spread of technology, changing political issues","choices":["The spread of technology","Geography","Raw materials","Population size"],"explain":"The five are economic interdependence, transnational actors, nationalism in weak states, the spread of technology, and changing political issues. Nye says geography, population, and raw materials matter less than they used to."},{"id":"PAR-400-1","cat":"PAR","value":400,"week":2,"reading":"Mearsheimer","slide":"Hegemons & Relative Power","clue":"A state that asks “am I gaining more than my rival?” and not just “am I better off than before?” cares about which kind of power?","answer":"Relative power","choices":["Relative power","Absolute power","Soft power","Psychological power"],"explain":"Relative power is zero-sum: what matters is the distribution of capabilities. Absolute power looks only at the size of your own gains."},{"id":"PAR-400-2","cat":"PAR","value":400,"week":1,"reading":"Nye","slide":"Liberalism / Idealism","clue":"Realists and liberals disagree about who matters in world politics. What kind of actor do liberals stress that realists tend to downplay?","answer":"Non-state actors","choices":["Non-state actors","Great powers","Hegemons","Sovereign states"],"explain":"For realists, states are the dominant actors. Liberals say non-state actors matter too."},{"id":"PAR-400-3","cat":"PAR","value":400,"week":1,"reading":"Waltz","slide":"The System Has Three Big Features","clue":"Waltz contrasts anarchy with another ordering principle, one in which someone is in charge, as inside a state. What is it?","answer":"Hierarchy","choices":["Hierarchy","Chaos","Bipolarity","Self-help"],"explain":"The opposite of anarchy is hierarchy, not order. Anarchy is not chaos; it just means no authority above states."},{"id":"PAR-400-4","cat":"PAR","value":400,"week":1,"reading":"Nye","slide":"Liberalism / Idealism","clue":"Realists say states seek power in the service of security. According to liberals, what else do states seek?","answer":"Welfare","choices":["Welfare","Hegemony","Territory","Revenge"],"explain":"In the liberal view, states seek welfare, not only power, and genuine cooperation is possible."},{"id":"PAR-500-1","cat":"PAR","value":500,"week":2,"reading":"Mearsheimer","slide":"What Inhibits Cooperation Among States?","clue":"Mearsheimer names two things that inhibit cooperation among states. Concern about relative gains is one. What is the other?","answer":"Cheating","choices":["Cheating","Imperfect information","The fog of war","Uncertainty about others' resolve"],"explain":"Under anarchy there is no enforcer to guarantee that the other side keeps its word. The other three are his sources of miscalculation."},{"id":"PAR-500-2","cat":"PAR","value":500,"week":2,"reading":"Mearsheimer","slide":"When Do States Pursue Non-Security Goals?","clue":"During the Cold War the U.S. promoted democracy abroad, yet helped overthrow elected governments tilting toward the Soviet Union. Which theory expects this, because security logic wins when goals conflict?","answer":"Offensive realism (Mearsheimer)","choices":["Offensive realism","Liberalism","Constructivism","Cosmopolitanism"],"explain":"Offensive realism says states pursue non-security goals only when they do not conflict with balance-of-power logic."},{"id":"PAR-500-3","cat":"PAR","value":500,"week":2,"reading":"Mearsheimer","slide":"Hegemons & Relative Power","clue":"In Mearsheimer's theory, what exactly is a hegemon?","answer":"The only great power in the system","choices":["The only great power in the system","The strongest of several great powers","Any state with nuclear weapons","The leader of an alliance"],"explain":"A hegemon is not just the strongest state. It is the only great power in the system."},{"id":"PAR-500-4","cat":"PAR","value":500,"week":2,"reading":"Keck & Sikkink","slide":"Four Kinds of Network Politics","clue":"A human rights network publicly holds a government to principles the government itself endorsed earlier. Which of Keck and Sikkink's four kinds of network politics is this?","answer":"Accountability politics","choices":["Accountability politics","Information politics","Symbolic politics","Leverage politics"],"explain":"Accountability politics holds powerful actors to their own previously stated policies or principles."},{"id":"REG-100-1","cat":"REG","value":100,"week":12,"reading":"Sagan; Mearsheimer","slide":"How Did They Do?","clue":"South Africa joined this treaty in 1991 after giving up its nuclear weapons program, China and France joined in 1992, and Belarus, Kazakhstan, and Ukraine joined as non-nuclear states. Which treaty is it?","answer":"The Non-Proliferation Treaty (NPT)","choices":["The Non-Proliferation Treaty (NPT)","The Rome Statute","SALT I","The UN Charter"],"explain":"In the early 1990s nonproliferation spread, not the managed proliferation Mearsheimer had prescribed."},{"id":"REG-100-2","cat":"REG","value":100,"week":9,"reading":"UN system","slide":"The Secretariat, and Much More","clue":"What is the title of the official who leads the UN Secretariat?","answer":"Secretary-General","choices":["Secretary-General","President of the General Assembly","High Commissioner","Director-General"],"explain":"The Secretariat is the UN's main administrative organ. Its staff may not take instructions from any source but the UN."},{"id":"REG-100-3","cat":"REG","value":100,"week":9,"reading":"ICC debate","slide":"The ICC: Context for the Debate","clue":"Which treaty, in force since 2002, established the International Criminal Court?","answer":"The Rome Statute","choices":["The Rome Statute","The UN Charter","The Bonn Agreement","The Non-Proliferation Treaty"],"explain":"The ICC was established in 2002 under the Rome Statute. The United States, Russia, China, and Iran are not parties."},{"id":"REG-100-4","cat":"REG","value":100,"week":9,"reading":"UN system","slide":"The General Assembly","clue":"In the UN General Assembly, how are votes distributed among member states?","answer":"One state, one vote","choices":["One state, one vote","Votes weighted by population","Votes weighted by budget share","Only the permanent five vote"],"explain":"Every state has one vote, whatever its size. Each government may send up to five representatives."},{"id":"REG-200-1","cat":"REG","value":200,"week":9,"reading":"Johns","slide":"Johns: Competing Perspectives on International Law","clue":"Which scholar presents three competing perspectives on international law, including a “critical” one in which law reflects power more than consent?","answer":"Johns","choices":["Johns","Simmons","Keohane","Rodrik"],"explain":"Johns's three perspectives each make different assumptions about whether and how law affects state behavior."},{"id":"REG-200-2","cat":"REG","value":200,"week":7,"reading":"Rodrik","slide":"Rodrik's Rules, Continued","clue":"Which scholar says international economic agreements should lay down “traffic rules” for managing the interface among national institutions?","answer":"Rodrik","choices":["Rodrik","Frankel","Gilpin","Keohane"],"explain":"This is one of Rodrik's rules for the global economy. Another: countries have the right to protect their own regulations and institutions."},{"id":"REG-200-3","cat":"REG","value":200,"week":9,"reading":"Raustiala & Jeronimo","slide":"Raustiala and Jeronimo: Why the UN Still Matters","clue":"Which pair of authors argue that the UN is the best tool for a rules-based international order, and ask how it fares when the great powers are at odds?","answer":"Raustiala and Jeronimo","choices":["Raustiala and Jeronimo","Martin and Simmons","Haass and O'Sullivan","Keck and Sikkink"],"explain":"Their answer: great power rivalry makes the UN more relevant, not less."},{"id":"REG-200-4","cat":"REG","value":200,"week":7,"reading":"Martin & Simmons","slide":"Martin and Simmons: International Institutions","clue":"Which pair of scholars say research should ask how institutions matter, and sort institutional effects into convergent and divergent?","answer":"Martin and Simmons","choices":["Martin and Simmons","Raustiala and Jeronimo","Feaver and Lorber","Nye and Welch"],"explain":"For Martin and Simmons, institutions are the object of strategic choice and they also constrain actors' behavior."},{"id":"REG-300-1","cat":"REG","value":300,"week":9,"reading":"UN system","slide":"The Security Council","clue":"The Security Council votes 14 to 1 for a substantive resolution, but the single “no” comes from France. What happens to the resolution?","answer":"It fails, because a permanent member vetoed it","choices":["It fails: a permanent member vetoed it","It passes: nine votes are enough","It passes unless a second permanent member objects","It goes to the General Assembly for a binding vote"],"explain":"Decisions need 9 of 15 votes, but on substantive questions any of the five permanent members can veto."},{"id":"REG-300-2","cat":"REG","value":300,"week":9,"reading":"Keohane","slide":"The Democratic Deficit","clue":"A critic complains that international organizations are run by technocrats, not elected officials. What is this concern called?","answer":"The democratic deficit","choices":["The democratic deficit","The selection effect","The security dilemma","Weaponized interdependence"],"explain":"The counterargument: international organizations answer to governments, which answer to their people."},{"id":"REG-300-3","cat":"REG","value":300,"week":7,"reading":"Rodrik","slide":"Trade as an Intervention in Domestic Institutions","clue":"A country restricts imports that threaten damage to its domestic regulatory arrangements. Rodrik would allow this by broadening fair trade to include what kind of dumping?","answer":"Social dumping","choices":["Social dumping","Currency dumping","Predatory dumping","Strategic dumping"],"explain":"Rodrik sees trade as an intervention into domestic institutions and proposes adding social dumping to the concept of fair trade."},{"id":"REG-300-4","cat":"REG","value":300,"week":9,"reading":"Raustiala & Jeronimo","slide":"Lessons from the Cold War","clue":"In Raustiala and Jeronimo's Cold War case study, a UN peacekeeping force deployed after independence and also served as a buffer to keep Lumumba from moving too close to the USSR. Which country was it?","answer":"The Congo","choices":["The Congo","Korea","Cuba","Vietnam"],"explain":"The Security Council stayed active in the Cold War because both superpowers wanted to preserve their special powers and privileges on the Council."},{"id":"REG-400-1","cat":"REG","value":400,"week":9,"reading":"UN system; ICC debate","slide":"ECOSOC, the Trusteeship Council, and the ICJ","clue":"The ICJ and the ICC are easy to confuse. Which one is the UN's primary judicial body, with 15 judges elected by the Security Council and the General Assembly, and a jurisdiction that states must voluntarily accept?","answer":"The International Court of Justice (ICJ)","choices":["The International Court of Justice (ICJ)","The International Criminal Court (ICC)","The Trusteeship Council","The Security Council"],"explain":"The ICJ sits in The Hague. The ICC, set up under the Rome Statute, investigates and tries genocide, war crimes, crimes against humanity, and the crime of aggression."},{"id":"REG-400-2","cat":"REG","value":400,"week":9,"reading":"UN system","slide":"The Security Council","clue":"The General Assembly and the Security Council differ in legal force. Which one can make binding decisions, including sanctions and the use of force?","answer":"The Security Council","choices":["The Security Council","The General Assembly","The Economic and Social Council","The Secretariat"],"explain":"General Assembly resolutions are recommendations. The Security Council can make binding decisions under Chapter VII."},{"id":"REG-400-3","cat":"REG","value":400,"week":9,"reading":"Johns","slide":"The Sociological Perspective","clue":"In Johns's contractual view, states have preferences and make law by consenting to rules. Which of Johns's perspectives assumes that state preferences are malleable, so that law can change what states want?","answer":"The sociological perspective","choices":["The sociological perspective","The critical perspective","The contractual perspective","The realist perspective"],"explain":"The sociological perspective says persuasion and socialization can change preferences over time."},{"id":"REG-400-4","cat":"REG","value":400,"week":7,"reading":"Frankel","slide":"“New Trade Theory”","clue":"Classical trade theory says trade raises the level of a country's income. What does new trade theory say openness can permanently affect?","answer":"The country's growth rate","choices":["Its growth rate","Its exchange rate","Its population","Its tariff revenue"],"explain":"Classical gains are static and raise the level of income. New trade theory says openness can raise the growth rate, and growth compounds."},{"id":"REG-500-1","cat":"REG","value":500,"week":9,"reading":"Johns","slide":"Four Challenges to Cooperation","clue":"Johns names four challenges to cooperation: coordination, collaboration, commitment, and one more. What is the fourth?","answer":"Screening","choices":["Screening","Enforcement","Verification","Bargaining"],"explain":"The four challenges are coordination, collaboration, commitment, and screening problems."},{"id":"REG-500-2","cat":"REG","value":500,"week":9,"reading":"Simmons","slide":"How Treaties Can Change State Behavior","clue":"Simmons lists ways treaties can change state behavior. Which mechanism is the constructivist argument?","answer":"Socialization","choices":["Socialization","Reciprocity","Reputation","Credible commitment"],"explain":"Simmons's three mechanisms: reciprocity and reputation, credible commitments, and socialization, which is the constructivist argument."},{"id":"REG-500-3","cat":"REG","value":500,"week":9,"reading":"UN system","slide":"The General Assembly","clue":"On “important questions” such as peace and security, new members, and the budget, what majority does the General Assembly need?","answer":"A two-thirds majority","choices":["Two-thirds","A simple majority","Unanimity","Nine of fifteen votes"],"explain":"Most General Assembly decisions take a simple majority, but important questions need two-thirds."},{"id":"REG-500-4","cat":"REG","value":500,"week":12,"reading":"Sagan","slide":"Two Points of Agreement","clue":"Sagan reports a consensus in the proliferation literature about the NPT, one he argues against. What does that consensus say?","answer":"That the NPT has no significant effect on proliferation","choices":["It has no significant effect on proliferation","It has stopped proliferation entirely","It speeds up proliferation","It matters only for democracies"],"explain":"The literature's consensus is that the NPT has no significant effect on the likelihood of proliferation. Sagan disagrees."},{"id":"ECO-100-1","cat":"ECO","value":100,"week":10,"reading":"Feaver & Lorber","slide":"Targeted vs. Comprehensive Sanctions","clue":"What do we call sanctions that focus pressure on elites, with tools such as travel bans and asset freezes?","answer":"Targeted sanctions","choices":["Targeted sanctions","Comprehensive sanctions","Reputational financial sanctions","Export controls"],"explain":"Comprehensive sanctions hit broad swaths of the population. Targeted sanctions focus on the leadership and its supporters."},{"id":"ECO-100-2","cat":"ECO","value":100,"week":6,"reading":"Gilpin","slide":"Three Conceptions of Political Economy","clue":"Gilpin lays out three conceptions of political economy. Liberalism and Marxism are two. What is the third?","answer":"Mercantilism","choices":["Mercantilism","Realism","Constructivism","Populism"],"explain":"The three conceptions are liberalism, Marxism, and mercantilism, and they vary along five dimensions."},{"id":"ECO-100-3","cat":"ECO","value":100,"week":10,"reading":"Farrell & Newman","slide":"Weaponized Interdependence","clue":"What is Farrell and Newman's term for turning the economic ties between states into tools of coercion?","answer":"Weaponized interdependence","choices":["Weaponized interdependence","Coercive diplomacy","Conditional engagement","Social dumping"],"explain":"The tools include sanctions, supply-chain attacks, and export controls. It is a byproduct of globalization."},{"id":"ECO-100-4","cat":"ECO","value":100,"week":6,"reading":"Gilpin","slide":"How Do Economics and Politics Differ?","clue":"In Gilpin's own formulation, economics is about wealth. What is politics about?","answer":"Power","choices":["Power","The budget","Structure","Process"],"explain":"Gilpin: economics is wealth, politics is power. Kindleberger contrasts market and budget; Keohane and Nye contrast process and structure."},{"id":"ECO-200-1","cat":"ECO","value":200,"week":10,"reading":"Haass & O'Sullivan","slide":"Two Practitioners","clue":"Which pair of authors wrote “Honey and Vinegar,” on when engagement and incentives make sense?","answer":"Haass and O'Sullivan","choices":["Haass and O'Sullivan","Feaver and Lorber","Farrell and Newman","Keck and Sikkink"],"explain":"Haass and O'Sullivan write as practitioners about when to engage and how to carry it out."},{"id":"ECO-200-2","cat":"ECO","value":200,"week":10,"reading":"Feaver & Lorber","slide":"Feaver and Lorber: The New Financial Levers","clue":"Which pair of authors analyze reputational financial sanctions, the “new financial levers” of coercive diplomacy?","answer":"Feaver and Lorber","choices":["Feaver and Lorber","Haass and O'Sullivan","Farrell and Newman","Martin and Simmons"],"explain":"Feaver and Lorber ask what makes sticks bite, and where reputational financial sanctions fit."},{"id":"ECO-200-3","cat":"ECO","value":200,"week":6,"reading":"Rodrik","slide":"It depends on whom trade empowers.","clue":"Which economist argues that whether trade brings peace or conflict “depends on whom trade empowers”?","answer":"Rodrik","choices":["Rodrik","Gilpin","Frankel","Kindleberger"],"explain":"Rodrik's thesis in “The Two Faces of Free Trade”: not whether there is trade, but who gains leverage from it."},{"id":"ECO-200-4","cat":"ECO","value":200,"week":10,"reading":"Feaver & Lorber","slide":"Coercive Diplomacy","clue":"Which thinker, cited by Feaver and Lorber, said the key to successful coercion is the threat of more punishment to come?","answer":"Schelling","choices":["Schelling","Gilpin","Haass","Keohane"],"explain":"For Schelling, limited pain signals that the coercer is willing and able to ratchet it up."},{"id":"ECO-300-1","cat":"ECO","value":300,"week":10,"reading":"Feaver & Lorber","slide":"Reputational Financial Sanctions","clue":"In 2005 the U.S. Treasury ordered U.S. banks to close their accounts with Banco Delta Asia in Macau, and about two dozen other banks then cut back their business with North Korea. What kind of sanction is this?","answer":"A reputational financial sanction","choices":["A reputational financial sanction","A comprehensive sanction","Conditional engagement","An export control"],"explain":"Reputational financial sanctions chill investment by threatening the financial reputations of legitimate institutions."},{"id":"ECO-300-2","cat":"ECO","value":300,"week":10,"reading":"Farrell & Newman","slide":"Weaponized interdependence is a byproduct of globalization.","clue":"Dollar-clearing banks, SWIFT, and rare earth processing are examples of points that the world economy's networks run through. Whoever controls one gains leverage over everyone who depends on it. What is such a point called?","answer":"A hub (also accept: a chokepoint)","choices":["A hub","A carrot","A regime","A pole"],"explain":"Globalization tied the world economy together through networks that run through a few hubs, and control of a hub is leverage."},{"id":"ECO-300-3","cat":"ECO","value":300,"week":6,"reading":"Rodrik","slide":"Free Trade as an Instrument of Coercion","clue":"Rodrik notes that Britain imposed free trade “through the barrel of a gun.” Which wars are his example?","answer":"The Opium Wars","choices":["The Opium Wars","The Boer Wars","The Napoleonic Wars","The Crimean War"],"explain":"The same free trade policy that reformers favored also served militarism, as in the Opium Wars."},{"id":"ECO-300-4","cat":"ECO","value":300,"week":10,"reading":"Haass & O'Sullivan","slide":"Question 1: When Does Engagement Make Sense?","clue":"Kim Jong Un controls North Korea's policy largely on his own. Which of Haass and O'Sullivan's conditions favoring conditional engagement does that satisfy?","answer":"Highly concentrated decision-making","choices":["Highly concentrated decision-making","Adequate domestic support in the U.S.","Intense coordination with allies","A well-defined roadmap"],"explain":"The best candidates for conditional engagement are countries where decision-making is highly concentrated."},{"id":"ECO-400-1","cat":"ECO","value":400,"week":10,"reading":"Feaver & Lorber","slide":"Targeted vs. Comprehensive Sanctions","clue":"Comprehensive and targeted sanctions suit different targets. According to the emerging consensus, comprehensive sanctions work better against which kind of regime?","answer":"Democracies","choices":["Democracies","Autocracies","Monarchies","Military regimes"],"explain":"The emerging consensus: targeted sanctions work better against autocracies, comprehensive sanctions against democracies."},{"id":"ECO-400-2","cat":"ECO","value":400,"week":6,"reading":"Gilpin","slide":"Gilpin's Table 1 (p. 269)","clue":"On the relationship between economics and politics, liberalism says economics SHOULD determine politics. What does Marxism say?","answer":"Economics DOES determine politics","choices":["Economics does determine politics","Politics determines economics","Politics should determine economics","The two are unrelated"],"explain":"Liberalism makes a normative claim (should), Marxism a positive one (does). Mercantilism reverses the direction: politics determines economics."},{"id":"ECO-400-3","cat":"ECO","value":400,"week":10,"reading":"Haass & O'Sullivan","slide":"Question 2: How Should Engagement Be Carried Out?","clue":"Haass and O'Sullivan give advice on how to carry out engagement. The more complex the relationship with the target, the smaller the role what should play?","answer":"Linkage","choices":["Linkage","Allies","Civil society","Credible penalties"],"explain":"They advise coordinating intensely with allies, engaging civil society, and backing incentives with credible penalties, but limiting linkage in complex relationships."},{"id":"ECO-400-4","cat":"ECO","value":400,"week":10,"reading":"Feaver & Lorber","slide":"Sanctions Cut Both Ways","clue":"Why do Feaver and Lorber call economic sanctions a double-edged sword?","answer":"They impose pain on the sender as well as the target","choices":["They hurt the sender as well as the target","They strengthen the target's economy over time","They always provoke military retaliation","They work only the first time they are used"],"explain":"Commerce denied to the target is also denied to the sender, so sanctions are contests in pain."},{"id":"ECO-500-1","cat":"ECO","value":500,"week":10,"reading":"Feaver & Lorber","slide":"Three Determinants of Successful Coercion","clue":"Feaver and Lorber name three determinants of successful coercion: the stakes, the clarity of the signal, and what third factor?","answer":"The pain tolerance and mitigation strategies available to the participants","choices":["Pain tolerance and mitigation strategies","The number of allies on each side","The size of the sender's economy","The target's regime type"],"explain":"The three are the demands or stakes, the clarity and perception of the signal, and pain tolerance and mitigation."},{"id":"ECO-500-2","cat":"ECO","value":500,"week":6,"reading":"Gilpin","slide":"Adding Gilpin's Own Column","clue":"Gilpin's own view of economics and politics is reciprocal. In the short term the distribution of power shapes the economy. What can happen in the long term?","answer":"Economic forces can usher in a new dominant power","choices":["Economic forces can bring a new dominant power","Politics stops mattering","Class conflict ends the system","Markets reach a permanent equilibrium"],"explain":"For Gilpin the dominant power sets the economic system in the short term, but in the long term economic forces can change who dominates."},{"id":"ECO-500-3","cat":"ECO","value":500,"week":6,"reading":"Rodrik","slide":"“A Victim of Its Own Success”","clue":"Rodrik says the postwar free trade regime became “a victim of its own success.” In his words, what did it become a source of?","answer":"International discord instead of harmony","choices":["International discord instead of harmony","Lasting peace among trading states","Growth for Western economies only","Stronger labor movements everywhere"],"explain":"After 1945 commercial diplomacy replaced wars, but the regime's very success turned it into a source of international discord."},{"id":"ECO-500-4","cat":"ECO","value":500,"week":6,"reading":"Gilpin","slide":"What Do These Theories of Change Mean?","clue":"Each of Gilpin's three conceptions has a theory of change. Which conception sees a “dynamic equilibrium,” with gradual, adaptive change toward an integrated world economy?","answer":"Liberalism","choices":["Liberalism","Marxism","Mercantilism","Gilpin's own view"],"explain":"Marxism sees a tendency toward disequilibrium; mercantilism sees change when the distribution of power shifts."},{"id":"SEC-100-1","cat":"SEC","value":100,"week":5,"reading":"Jervis","slide":"The Security Dilemma, and When It Bites","clue":"What do we call the situation in which an increase in one state's security decreases the security of others?","answer":"The security dilemma","choices":["The security dilemma","The balance of terror","A commitment problem","Bandwagoning"],"explain":"The tragic part: nobody has to want war for the spiral to run."},{"id":"SEC-100-2","cat":"SEC","value":100,"week":5,"reading":"Walt","slide":"Balancing","clue":"What is the term for aligning against a stronger or more threatening state or alliance, to protect yourself from it?","answer":"Balancing","choices":["Balancing","Bandwagoning","Free riding","Appeasement"],"explain":"States balance to protect themselves, and joining the weaker side also raises a new member's influence within the alliance."},{"id":"SEC-100-3","cat":"SEC","value":100,"week":1,"reading":"Waltz","slide":"So What Does Anarchy Imply?","clue":"Under anarchy the core imperative for states is “take care of yourself.” What does Waltz call this kind of system?","answer":"A self-help system","choices":["A self-help system","A collective security system","A hierarchy","A hegemony"],"explain":"With no global police force, states cannot count on anyone else to protect them, so they must provide their own security."},{"id":"SEC-100-4","cat":"SEC","value":100,"week":5,"reading":"Three Images","slide":"Three Images and the Causes of War","clue":"In the three images of the causes of war, the first is the individual and the second is the state. What is the third?","answer":"The international system as a whole","choices":["The international system","The economy","The alliance","The military"],"explain":"First image: the individual. Second: the state (ideology, domestic politics, regime type). Third: the international system."},{"id":"SEC-200-1","cat":"SEC","value":200,"week":5,"reading":"Jervis","slide":"Jervis: Offense, Defense, and the Security Dilemma","clue":"Which scholar says the security dilemma depends on two variables: whether offense or defense has the advantage, and whether offensive and defensive weapons can be told apart?","answer":"Jervis","choices":["Jervis","Walt","Fearon","Lake"],"explain":"Jervis's two variables generate four worlds, from doubly dangerous to doubly stable."},{"id":"SEC-200-2","cat":"SEC","value":200,"week":5,"reading":"Walt","slide":"Walt: Alliances, Balancing and Bandwagoning","clue":"Which realist scholar analyzes alliances through the concepts of balancing and bandwagoning?","answer":"Walt","choices":["Walt","Waltz","Jervis","Mearsheimer"],"explain":"Walt, not Waltz. Walt writes about alliances; Waltz wrote about the anarchic structure of world politics."},{"id":"SEC-200-3","cat":"SEC","value":200,"week":5,"reading":"Fearon","slide":"Fearon: Rationalist Explanations for War","clue":"Which scholar asks why states fight costly wars when they could strike a bargain first, and answers with private information and commitment problems?","answer":"Fearon","choices":["Fearon","Jervis","Lake","Walt"],"explain":"Fearon's puzzle: war is costly and both sides know it, so there should be a deal both prefer to fighting."},{"id":"SEC-200-4","cat":"SEC","value":200,"week":5,"reading":"Lake","slide":"Lake: Why “Isms” Are Evil","clue":"Which scholar argues that “isms” are evil, and that we should be analytically eclectic instead of picking teams?","answer":"Lake","choices":["Lake","Fearon","Walt","Waltz"],"explain":"Lake says academic sects harm understanding; the traditions are complementary pathways, not rival teams."},{"id":"SEC-300-1","cat":"SEC","value":300,"week":5,"reading":"Jervis","slide":"Dimension 1: Offense vs. Defense in 1914 and 1939","clue":"Before World War I, military leaders in all countries shared a “cult of the offensive.” Which actually had the advantage: the offense or the defense?","answer":"The defense","choices":["The defense","The offense","Neither","Whichever side had more allies"],"explain":"Leaders believed the offense had the advantage. In reality the defense did. What drives behavior is the perceived balance."},{"id":"SEC-300-2","cat":"SEC","value":300,"week":5,"reading":"Jervis","slide":"Dimension 1: Offense vs. Defense in 1914 and 1939","clue":"Before World War II in Europe, almost everyone believed the defense had the advantage, and they were wrong. Which leader was the exception?","answer":"Hitler","choices":["Hitler","Chamberlain","Stalin","Churchill"],"explain":"Everyone except Hitler believed the defense had the advantage. In that context, Chamberlain's restraint made sense."},{"id":"SEC-300-3","cat":"SEC","value":300,"week":5,"reading":"Three Images","slide":"Three Images: World War I","clue":"Applying the three images to World War I: the increasing rigidity of alliances over time is an explanation at which image?","answer":"The third image (the international system)","choices":["The third image (the international system)","The second image (the state)","The first image (the individual)","“Image 1.5” (leaders' beliefs)"],"explain":"Nationalism and imperialism are second-image causes; rigid alliances are a feature of the system, the third image."},{"id":"SEC-300-4","cat":"SEC","value":300,"week":5,"reading":"Walt","slide":"When Do States Balance vs. Bandwagon?","clue":"A weak state sits next to a threatening great power and has few possible allies, so it sides with that power. What does Walt call this?","answer":"Bandwagoning","choices":["Bandwagoning","Balancing","Free riding","Preemption"],"explain":"Weak states are more likely to bandwagon, especially when the threat is close and allies are scarce."},{"id":"SEC-400-1","cat":"SEC","value":400,"week":5,"reading":"Walt","slide":"What Does Each World Look Like?","clue":"In a balancing world, threatening states provoke others to align against them. In a world where bandwagoning dominates, what happens to great powers that look strong and potentially aggressive?","answer":"They are rewarded","choices":["They are rewarded","They are punished","They are ignored","They lose their allies"],"explain":"The same behavior is punished in a balancing world and rewarded in a bandwagoning one, where a small defeat can snowball."},{"id":"SEC-400-2","cat":"SEC","value":400,"week":5,"reading":"Jervis","slide":"Jervis's Four Worlds","clue":"In Jervis's four worlds, which combination is “doubly dangerous”?","answer":"The offense has the advantage, and offensive weapons cannot be distinguished from defensive ones","choices":["Offense has the advantage, and the two postures cannot be told apart","Defense has the advantage, and the two can be told apart","Offense has the advantage, but the two can be told apart","Defense has the advantage, but the two cannot be told apart"],"explain":"Doubly dangerous: offense advantage and no differentiation. Doubly stable is the opposite corner."},{"id":"SEC-400-3","cat":"SEC","value":400,"week":5,"reading":"Fearon","slide":"Fearon's Two Mechanisms","clue":"Fearon's commitment problems include preemption and prevention. Which one arises because states cannot trust each other to keep a bargain as power shifts?","answer":"Prevention","choices":["Prevention","Preemption","Strategic territory","Private information"],"explain":"Preemption: no one can credibly commit not to attack first. Prevention: states cannot trust each other to keep a bargain as power shifts."},{"id":"SEC-400-4","cat":"SEC","value":400,"week":5,"reading":"Jervis","slide":"What Does “Advantage” Actually Mean?","clue":"Jervis's dollar test: a state must spend more than one dollar on defensive forces to offset each dollar its rival spends on forces that could attack. Who has the advantage?","answer":"The offense","choices":["The offense","The defense","Neither","The richer state"],"explain":"If defending costs more than attacking, dollar for dollar, the offense has the advantage."},{"id":"SEC-500-1","cat":"SEC","value":500,"week":5,"reading":"Fearon","slide":"Fearon's Two Mechanisms","clue":"Fearon's first mechanism for war is private information about resolve and capabilities, combined with what?","answer":"An incentive to misrepresent it (to bluff)","choices":["An incentive to misrepresent it","An incentive to share it","A cult of the offensive","A rigid alliance system"],"explain":"States hold private information about resolve and capabilities and have every incentive to bluff about both."},{"id":"SEC-500-2","cat":"SEC","value":500,"week":5,"reading":"Jervis","slide":"Jervis's Four Worlds","clue":"In Jervis's four worlds, suppose the offense has the advantage but offensive weapons CAN be distinguished from defensive ones. What does Jervis say about that world?","answer":"No security dilemma, but aggression is possible","choices":["No security dilemma, but aggression is possible","It is doubly dangerous","It is doubly stable","A security dilemma, but security requirements may be compatible"],"explain":"When postures can be told apart, status quo states can follow a different policy than aggressors and get warning."},{"id":"SEC-500-3","cat":"SEC","value":500,"week":5,"reading":"Walt","slide":"When Do States Balance vs. Bandwagon?","clue":"According to Walt, what is the optimal policy for a weak state that does choose to balance?","answer":"To free ride","choices":["Free ride","Arm heavily","Strike first","Switch sides often"],"explain":"A weak state adds little to a defensive coalition, so its best policy inside one is to free ride."},{"id":"SEC-500-4","cat":"SEC","value":500,"week":5,"reading":"Lake","slide":"Lake: Why “Isms” Are Evil","clue":"One of Lake's five pathologies of “isms” is to mistake research traditions for what?","answer":"Actual theories","choices":["Actual theories","Policy advice","Historical facts","Moral positions"],"explain":"Lake's five: reify traditions into groups, reward extremism, mistake traditions for theories, choose most likely cases, and seek dominance."},{"id":"NUC-100-1","cat":"NUC","value":100,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Two Key Terms","clue":"What verb means to dissuade through fear?","answer":"Deter","choices":["Deter","Contain","Appease","Pre-empt"],"explain":"After the hydrogen bomb, deterrence became the key strategy."},{"id":"NUC-100-2","cat":"NUC","value":100,"week":11,"reading":"Nye, UGCC ch. 5","slide":"The Balance of Terror","clue":"What three-word phrase describes the nuclear standoff between the superpowers, which coincided with bipolarity?","answer":"The balance of terror","choices":["The balance of terror","The balance of threat","The security dilemma","The long peace"],"explain":"The balance of terror and bipolarity arrived together, which makes it hard to say which one kept the peace."},{"id":"NUC-100-3","cat":"NUC","value":100,"week":12,"reading":"Waltz","slide":"Preventive vs. Pre-emptive War","clue":"A state strikes first because the other country is about to attack it, aiming to destroy the enemy's ability to retaliate. What kind of war is this?","answer":"Pre-emptive war","choices":["Pre-emptive war","Preventive war","Limited war","Proxy war"],"explain":"Pre-emption means striking first against an attack that is about to come, to eliminate the opponent's ability to retaliate."},{"id":"NUC-100-4","cat":"NUC","value":100,"week":12,"reading":"Sagan","slide":"Two Sides of the Literature","clue":"In the proliferation literature, the “supply side” is the technical capability to develop nuclear weapons. What is the “demand side”?","answer":"The motivation to develop nuclear weapons","choices":["The motivation to develop them","The market price of uranium","Requests for help from nuclear allies","Public opinion in nuclear states"],"explain":"Supply side: technical capability. Demand side: motivation."},{"id":"NUC-200-1","cat":"NUC","value":200,"week":12,"reading":"Waltz","slide":"Waltz's Replies","clue":"Which scholar argues that nuclear weapons induce caution, especially in weak states, so that a world with more nuclear states is tolerable?","answer":"Waltz","choices":["Waltz","Sagan","Fukuyama","Nye"],"explain":"Waltz: a nuclear world is tolerable if nuclear states can send convincing deterrent messages."},{"id":"NUC-200-2","cat":"NUC","value":200,"week":12,"reading":"Sagan","slide":"Two Sides of the Literature","clue":"Which scholar reviews the proliferation literature and argues that supply-side work relies on inaccurate measures while demand-side work pays too little attention to the NPT?","answer":"Sagan","choices":["Sagan","Waltz","Kroenig","Mearsheimer"],"explain":"Sagan's review criticizes both halves of the literature and argues that the NPT deserves more attention."},{"id":"NUC-200-3","cat":"NUC","value":200,"week":12,"reading":"Mearsheimer","slide":"Mearsheimer: Back to the Future","clue":"Which scholar prescribed the limited, managed proliferation of nuclear weapons in post-Cold War Europe, ideally to Germany and no one else?","answer":"Mearsheimer","choices":["Mearsheimer","Waltz","Fukuyama","Sagan"],"explain":"Mearsheimer credited the Long Peace partly to nuclear weapons and feared a return to multipolarity in Europe."},{"id":"NUC-200-4","cat":"NUC","value":200,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Assessing Nuclear Deterrence","clue":"Deterrence needs two things. Capability, the means to retaliate, is one. What is the other?","answer":"Credibility","choices":["Credibility","Secrecy","Superiority","Surprise"],"explain":"Deterrence needs both the means to retaliate and a threat that the other side finds believable."},{"id":"NUC-300-1","cat":"NUC","value":300,"week":12,"reading":"Waltz","slide":"Preventive vs. Pre-emptive War","clue":"A state bombs a rival's nuclear facilities to stop a weapon the rival does not yet have, not to stop an attack that is about to come. By the course definitions, what kind of strike is that?","answer":"Preventive","choices":["Preventive","Pre-emptive","Retaliatory","Defensive"],"explain":"Preventive war attacks a country before it becomes strong. Pre-emptive war strikes first against an attack about to happen."},{"id":"NUC-300-2","cat":"NUC","value":300,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Why Did Khrushchev Back Down?","clue":"In the deal that ended the Cuban Missile Crisis, the U.S. pledged not to invade Cuba. What else did it quietly promise?","answer":"To remove U.S. missiles from Turkey","choices":["To remove U.S. missiles from Turkey","To withdraw from West Berlin","To end the embargo on Cuba","To share nuclear technology"],"explain":"Khrushchev agreed to withdraw the missiles in exchange for a no-invasion pledge and a quiet promise on the missiles in Turkey."},{"id":"NUC-300-3","cat":"NUC","value":300,"week":12,"reading":"Waltz","slide":"Seven Reasons to Go Nuclear","clue":"Waltz says a state without nuclear allies will want the bomb if some of its adversaries have it. Applied to Iran, which state's undeclared arsenal fits this reason?","answer":"Israel","choices":["Israel","Saudi Arabia","Turkey","Iraq"],"explain":"The class applied Waltz's seven reasons to Iran; Israel's undeclared arsenal fits the adversaries-have-them reason."},{"id":"NUC-300-4","cat":"NUC","value":300,"week":12,"reading":"Waltz","slide":"Waltz's bottom line (slide kicker)","clue":"Complete Waltz's bottom line: the likelihood of war decreases as deterrent and defensive capabilities do what?","answer":"Increase","choices":["Increase","Decrease","Are kept secret","Are shared with allies"],"explain":"Stronger deterrent and defensive capabilities make war less likely. This is easy to get backwards."},{"id":"NUC-400-1","cat":"NUC","value":400,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Assessing Nuclear Deterrence","clue":"Deterrence and defense are different. Deterrence prevents an attack by threatening punishment. What does defense do?","answer":"It limits the damage if an attack comes","choices":["Limits the damage if an attack comes","Threatens retaliation","Strikes before the enemy can","Persuades through attraction"],"explain":"Deterrence works on the attacker's decision; defense works on the consequences of an attack."},{"id":"NUC-400-2","cat":"NUC","value":400,"week":12,"reading":"Sagan","slide":"Applying the Literature to Iran","clue":"On the supply side of proliferation, which scholar asks why states sell or give sensitive nuclear assistance to others?","answer":"Kroenig","choices":["Kroenig","Sagan","Waltz","Huntington"],"explain":"Kroenig's question belongs to the supply side of the proliferation literature."},{"id":"NUC-400-3","cat":"NUC","value":400,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Why Did Khrushchev Back Down?","clue":"In 1962 the U.S. had roughly a 17-to-1 advantage in nuclear weapons, but the reading says the ratio was not the whole story. Apart from the terms of the deal, name one other reason Khrushchev backed down.","answer":"Either: the U.S. had a greater stake in nearby Cuba and could bring conventional forces to bear there; or fear, since even a few nuclear weapons could cause unbearable devastation","choices":["Fear of the devastation even a few nuclear weapons could cause","The Soviet Union had run out of missiles to deploy","The UN Security Council ordered a Soviet withdrawal","China threatened to intervene on the American side"],"explain":"More than the ratio: the U.S. had the greater stake and local conventional strength, and both sides feared devastation."},{"id":"NUC-400-4","cat":"NUC","value":400,"week":12,"reading":"Waltz","slide":"Waltz's Replies","clue":"Critics worry that states radical at home will use nuclear weapons recklessly abroad. What is Waltz's reply?","answer":"Behavior at home does not predict behavior abroad, and nuclear weapons induce caution, especially in weak states","choices":["Nuclear weapons induce caution, whatever a state does at home","Radical states cannot afford nuclear weapons","The NPT will keep radical states from getting them","The great powers will disarm them by force"],"explain":"Waltz: behavior at home does not predict behavior abroad, and nuclear weapons induce caution, especially in weak states."},{"id":"NUC-500-1","cat":"NUC","value":500,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Political Effects of the Hydrogen Bomb","clue":"Korea and Vietnam illustrate which political effect of the hydrogen bomb?","answer":"Limited war revived","choices":["Limited war revived","Crises replaced wars","Nuclear weapons became usable","Deterrence was abandoned"],"explain":"Korea and Vietnam were wars fought for limited aims, short of all-out war. Berlin and Cuba illustrate crises replacing wars."},{"id":"NUC-500-2","cat":"NUC","value":500,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Assessing Nuclear Deterrence","clue":"Why does judging whether nuclear deterrence worked require counterfactual analysis?","answer":"Because success is a non-event: we have to ask what would have happened without nuclear weapons","choices":["Success is a non-event: we must ask what would have happened without it","Most records of nuclear decisions are still classified","Neither superpower ever said what it would have done","Deterrence failed in every crisis where it was tried"],"explain":"When deterrence works, nothing happens. Would the Soviets have attacked Western Europe without the bomb?"},{"id":"NUC-500-3","cat":"NUC","value":500,"week":12,"reading":"Sagan","slide":"Two Points of Agreement","clue":"Per the literature Sagan reviews, regime type does not affect whether a state starts a weapons program. But which regime type is more likely to finish one and get the bomb?","answer":"Democracies","choices":["Democracies","Autocracies","Military regimes","Neither; there is no difference"],"explain":"Democracies and autocracies behave similarly; if anything, democracies are slightly more likely to go nuclear."},{"id":"NUC-500-4","cat":"NUC","value":500,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Deterrence and Just War","clue":"The paradox of nuclear deterrence: in order to prevent war, it threatens something the just war tradition forbids. What?","answer":"The mass killing of civilians","choices":["The mass killing of civilians","The use of conventional forces","The violation of sovereignty","Economic blockade"],"explain":"Just war requires means that discriminate and spare civilians. Can it be moral to threaten what it would be immoral to do?"},{"id":"GRB-100-1","cat":"GRB","value":100,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Two Key Terms","clue":"What was the U.S. Cold War policy of surrounding the Soviet Union with allies and bases while promoting a liberal order outside the Soviet sphere?","answer":"Containment","choices":["Containment","Détente","Rollback","Appeasement"],"explain":"Containment worked in large part because it was flexible and could be reinterpreted as circumstances changed."},{"id":"GRB-100-2","cat":"GRB","value":100,"week":8,"reading":"Thucydides","slide":"The Athenians: Skeptics","clue":"In the Melian Dialogue, which side says that “the strong do what they can and the weak suffer what they must”?","answer":"The Athenians","choices":["The Athenians","The Spartans","The Melians","The Persians"],"explain":"The Athenians argue that ruling whatever one can is “a general and necessary law of nature.”"},{"id":"GRB-100-3","cat":"GRB","value":100,"week":14,"reading":"Nye, UGCC ch. 10","slide":"Defining Terrorism","clue":"Complete Nye's definition of terrorism: premeditated, politically motivated violence against what kind of targets, by subnational groups?","answer":"Noncombatant targets","choices":["Noncombatant targets","Military targets","Government buildings","Economic infrastructure"],"explain":"Terrorism: premeditated, politically motivated violence against noncombatant targets by subnational groups."},{"id":"GRB-100-4","cat":"GRB","value":100,"week":14,"reading":"Brands","slide":"Brands: The Surge and the Withdrawal","clue":"What name is given to the 2007 increase in U.S. troops in Iraq, which Brands credits with improving security and reducing violence?","answer":"The surge","choices":["The surge","Operation Desert Storm","Operation Enduring Freedom","Operation Inherent Resolve"],"explain":"Brands says the surge provided security in key areas and bolstered the Sunni tribes' uprising against jihadists."},{"id":"GRB-200-1","cat":"GRB","value":200,"week":12,"reading":"Fukuyama","slide":"Fukuyama: The End of History?","clue":"Which scholar argued that Western liberal democracy is the end point of humanity's ideological evolution, “the end of history”?","answer":"Fukuyama","choices":["Fukuyama","Huntington","Mearsheimer","Carr"],"explain":"For Fukuyama, liberalism had triumphed over its rivals, fascism and communism."},{"id":"GRB-200-2","cat":"GRB","value":200,"week":12,"reading":"Huntington","slide":"Huntington: The Clash of Civilizations?","clue":"Which scholar predicted that after the Cold War “the great divisions among humankind and the dominating source of conflict will be cultural”?","answer":"Huntington","choices":["Huntington","Fukuyama","Mearsheimer","Walter"],"explain":"Huntington's clash of civilizations stresses religion and ethnicity, and the “kin-country syndrome.”"},{"id":"GRB-200-3","cat":"GRB","value":200,"week":8,"reading":"Carr","slide":"Good of the Whole vs. Good of the Part","clue":"Which scholar's “fundamental dilemma of international morality” pits the good of the whole against the good of the part?","answer":"Carr","choices":["Carr","Thucydides","Nye","Hafner-Burton"],"explain":"Carr: states feel an obligation to the international community but are reluctant to put it above their own country's good."},{"id":"GRB-200-4","cat":"GRB","value":200,"week":8,"reading":"Hafner-Burton","slide":"Hafner-Burton: Global Human Rights in the 21st Century","clue":"Which scholar asks why human rights violations endure despite the vast expansion of global efforts at human rights promotion?","answer":"Hafner-Burton","choices":["Hafner-Burton","Chenoweth","Carr","Crenshaw"],"explain":"Hafner-Burton names four challenges: state sovereignty, populism and the decline of the West, the rise of autocrats, and identity and beliefs."},{"id":"GRB-300-1","cat":"GRB","value":300,"week":8,"reading":"Thucydides; Nye","slide":"The Athenians: Skeptics","clue":"Nye describes three views of morality in international relations. Which one fits the Athenians in the Melian Dialogue?","answer":"Skeptics","choices":["Skeptics","State moralists","Cosmopolitans","Constructivists"],"explain":"Skeptics hold that moral categories have no meaning in international relations: might ignores right."},{"id":"GRB-300-2","cat":"GRB","value":300,"week":14,"reading":"Brands; Leffler","slide":"Why Iraq? Fear, Power, and Hubris","clue":"Brands, drawing on Leffler, names three causes of the Iraq War. Fear and power are two. What is the third, the belief that the war would be quick and cheap?","answer":"Hubris","choices":["Hubris","Oil","Revenge","Ideology"],"explain":"Fear of simmering dangers after 9/11, the power of an unrivaled United States, and hubris about a quick, cheap war."},{"id":"GRB-300-3","cat":"GRB","value":300,"week":14,"reading":"Chenoweth","slide":"Six Consensus Findings","clue":"One of Chenoweth's six consensus findings says a certain group's cooperation is critical to effective repression. Which group?","answer":"The security forces","choices":["The security forces","The business elite","The courts","The state media"],"explain":"Repression depends on the security forces going along, at its onset and for its success."},{"id":"GRB-300-4","cat":"GRB","value":300,"week":12,"reading":"Huntington","slide":"How Did They Do?","clue":"Mearsheimer, Fukuyama, and Huntington each forecast the post-Cold War world. Whose argument did the ethnic and religious war in Bosnia (1992–1995) seem to support?","answer":"Huntington's","choices":["Huntington's clash of civilizations","Fukuyama's end of history","Mearsheimer's managed proliferation","Waltz's nuclear peace"],"explain":"Bosnia was an ethnic and religious war, the kind of cultural conflict Huntington predicted."},{"id":"GRB-400-1","cat":"GRB","value":400,"week":3,"reading":"Lind","slide":"Lind: Multi-Ethnic Nationalism","clue":"In Lind's liberal nationalism, what kind of condition is nationalism for democracy?","answer":"Necessary but not sufficient","choices":["Necessary but not sufficient","Sufficient but not necessary","Both necessary and sufficient","Neither necessary nor sufficient"],"explain":"Liberal nationalism holds that democracy needs nationalism, but nationalism alone does not produce democracy."},{"id":"GRB-400-2","cat":"GRB","value":400,"week":8,"reading":"Nye","slide":"Cosmopolitans","clue":"State moralists see a society of states whose core rule is sovereignty. What kind of society do cosmopolitans see?","answer":"A society of individuals with universal human rights","choices":["A society of individuals with universal human rights","A society of states bound by treaties","No moral community at all","A society of civilizations"],"explain":"Cosmopolitans focus on individuals and on distributive justice. The standard objection to them is cultural relativism."},{"id":"GRB-400-3","cat":"GRB","value":400,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Three Schools of Thought","clue":"Three schools explain who caused the Cold War. Traditionalists blame Stalin and revisionists blame the United States. Whom or what do post-revisionists blame?","answer":"No one: the bipolar structure of the postwar balance of power","choices":["No one: the bipolar structure made conflict all but inevitable","Churchill and Britain","Both leaders equally, for personal ambition","The United Nations"],"explain":"Post-revisionists point to the structure of the system, not to either side's leaders."},{"id":"GRB-400-4","cat":"GRB","value":400,"week":14,"reading":"Walter","slide":"What Is New, and Why It Matters","clue":"Walter says the rebel groups in post-2003 civil wars pursue radical Islamist goals. What else is distinctive about the scope of their aims?","answer":"They are transnational rather than national (not just control of a government or a territory)","choices":["They are transnational rather than national","They are economic rather than political","They are local rather than national","They are secular rather than religious"],"explain":"The three differences: mostly in Muslim-majority countries, radical Islamist goals, and transnational aims."},{"id":"GRB-500-1","cat":"GRB","value":500,"week":11,"reading":"Nye, UGCC ch. 5","slide":"Containment's Ambiguities","clue":"Containment carried an ambiguity that mattered once Yugoslavia and then China broke with Moscow. What was it?","answer":"Whether to contain Soviet power or communist ideology","choices":["Whether to contain Soviet power or communist ideology","Whether to act through the UN or NATO","Whether to contain Germany or Japan","Whether to defend Europe or Asia first"],"explain":"Containing ideology instead of Soviet power is what led to Vietnam, where the West underestimated differences among communist states."},{"id":"GRB-500-2","cat":"GRB","value":500,"week":12,"reading":"Mearsheimer","slide":"Mearsheimer: Back to the Future","clue":"In Mearsheimer's 1990 forecast for post-Cold War Europe, which nuclear outcome was his worst case?","answer":"A nuclear-free Europe","choices":["A nuclear-free Europe","Managed proliferation to Germany","A nuclear-armed Soviet Union","A U.S. nuclear guarantee for Germany"],"explain":"His worst case was Britain, France, and the Soviet Union giving up their weapons. His prescription was limited, managed proliferation."},{"id":"GRB-500-3","cat":"GRB","value":500,"week":8,"reading":"Carr","slide":"Good of the Whole vs. Good of the Part, Continued","clue":"According to Carr, how can the states that profit most from the existing international order hope to maintain it in the long run?","answer":"By making sufficient concessions to those who profit from it least","choices":["By making concessions to those who profit least","By enforcing it with military power","By withdrawing from international institutions","By ignoring dissatisfied states"],"explain":"The states that gain most from the order have to give the most to keep it tolerable for the rest."},{"id":"GRB-500-4","cat":"GRB","value":500,"week":14,"reading":"Woods, Lacey & Murray","slide":"What Saddam Believed","clue":"On the eve of the 2003 war, what did Saddam Hussein fear more than an American invasion?","answer":"An internal revolt","choices":["An internal revolt","An Iranian attack","UN weapons inspectors","A French and Russian betrayal"],"explain":"After the 1991 Shiite and Kurdish uprisings, internal threats were his highest concern; the military's main job was protecting the regime."},{"id":"FIN-1","cat":"FINAL","value":0,"week":10,"reading":"Feaver & Lorber; Johns","slide":"The only sanctions we see applied are cases where the threat of sanctions did not work.","clue":"The only sanctions we see applied are the ones where the threat failed, and states tend to join the treaties they already intend to keep. What one problem do both observations describe?","answer":"A selection effect","choices":["A selection effect","A security dilemma","A commitment problem","Free riding"],"explain":"The cases we observe are not a random sample, so they can mislead us about how well sanctions or treaties work."},{"id":"FIN-2","cat":"FINAL","value":0,"week":5,"reading":"Fearon; Johns; Petraeus","slide":"Fearon's Two Mechanisms","clue":"Fearon uses it to explain war, Johns lists it among four challenges to cooperation, and it is the Week 14 slide heading for Petraeus's critique of U.S. exit-seeking in Afghanistan. What kind of problem is it?","answer":"A commitment problem","choices":["A commitment problem","A coordination problem","A screening problem","A collaboration problem"],"explain":"A commitment problem arises when an actor cannot credibly promise how it will behave later."},{"id":"FIN-3","cat":"FINAL","value":0,"week":14,"reading":"Fearon; Waltz; Leffler","slide":"Leffler: From Sanctions to War","clue":"One logic connects Fearon's “prevention” and the Week 12 definition of preventive war. Week 14 asked whether this logic, and not pre-emption, describes the 2003 invasion of Iraq. What is the logic?","answer":"Fight now to stop a rival from becoming a greater threat later","choices":["Fight now to stop a rival from becoming a greater threat later","Strike first because the enemy is about to attack","Retaliate in kind after being attacked","Threaten punishment to prevent an attack"],"explain":"Preventive war aims at a future threat, not an imminent attack. The Bush administration used the word pre-emption for Iraq."},{"id":"FIN-4","cat":"FINAL","value":0,"week":8,"reading":"Nye & Welch; Nye; Hafner-Burton","slide":"Challenges to Human Rights (1 of 2)","clue":"It is one of the two core characteristics of a state, the core rule for state moralists, and the first of Hafner-Burton's four challenges to human rights. What is it?","answer":"Sovereignty","choices":["Sovereignty","Territoriality","Anarchy","Legitimacy"],"explain":"Sovereignty is the right to govern a territory. State moralists build on it, and Hafner-Burton says it will always trump human rights."},{"id":"FIN-5","cat":"FINAL","value":0,"week":3,"reading":"Nye; Three Images; Lind","slide":"Five Trends Driving the Diffusion of Power","clue":"In weak states it is one of Nye's five trends, it is a second-image cause of World War I, and for Lind it is necessary but not sufficient for democracy. What is it?","answer":"Nationalism","choices":["Nationalism","Imperialism","Sovereignty","Populism"],"explain":"Nationalism in weak states diffuses power; French nationalism helped cause World War I; Lind's liberal nationalism ties it to democracy."}]};
